from collections import deque

def transform(grid):
    """
    Task-607a9d08 Transformation:
    - Combine cells with background colors first
    - Identify 7-colored regions and their noise neighbors
    - Keep 7 regions + adjacent noise pixels
    - Remove isolated noise (those not adjacent to 7)
    """
    if not grid or not grid[0]:
        return grid

    rows, cols = len(grid), len(grid[0])

    # Get background colors
    bg_colors = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] not in [7]:
                bg_colors.add(grid[r][c])

    # Step 1: Combine background cells
    combined = [[0] * cols for _ in range(rows)]
    visited = [[False] * cols for _ in range(rows)]

    for r in range(rows):
        for c in range(cols):
            if visited[r][c]:
                continue
            val = grid[r][c]
            if grid[r][c] not in [7]:
                combined[r][c] = val
                # Combine all adjacent background cells
                stack = [(r, c)]
                visited[r][c] = True
                while stack:
                    cr, cc = stack.pop()
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if not visited[nr][nc] and grid[nr][nc] in list(bg_colors):
                                # Mark as absorbed
                                visited[nr][nc] = True
                                stack.append((nr, nc))

    # Step 2: Find 7-regions and their adjacency
    result = [[0] * cols for _ in range(rows)]

    # Track where 7s are
    for r in range(rows):
        for c in range(cols):
            result[r][c] = combined[r][c]

    # Keep 7s as-is
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 7:
                result[r][c] = 7

    # Mark noise adjacent to 7s (orthogonally)
    noise_adjacent_to_7 = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != 7:
                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == 7:
                        noise_adjacent_to_7.add((r, c))
                        break

    # Keep 7 regions + their noise neighbors, remove everything else
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 7:
                result[r][c] = 7
            elif (r, c) in noise_adjacent_to_7:
                result[r][c] = grid[r][c]
            else:
                result[r][c] = 8  # Background

    return result

